    else if (ci < 17) ch = hex(win_lfsr[63 - 4*(ci-1) -: 4]);
    else if (ci < 4369) ch = hex(rec[17407 -: 4]);
    else if (ci == 4369) ch = 8'h0d;
    else ch = 8'h0a;
  end
